fun lastThree(items: List<String>): List<String> {
    val result = mutableListOf<String>()
    for (i in items.size - 3..items.size) {
        result.add(items[i])
    }
    return result
}

fun readConfig(path: String): String {
    val reader = File(path).bufferedReader()
    val text = reader.readText()
    reader.close()
    return text
}

