fun p(l: List<Int>, t: Int): Boolean {
    for (i in l.indices) for (j in i + 1 until l.size) if (l[i] + l[j] == t) return true
    return false
}

interface GreetingStrategy { fun greet(name: String): String }
class DefaultGreetingStrategy : GreetingStrategy {
    override fun greet(name: String) = "Hello, $name"
}
class GreetingStrategyFactory {
    fun create(): GreetingStrategy = DefaultGreetingStrategy()
}
class Greeter(private val factory: GreetingStrategyFactory) {
    fun greet(name: String) = factory.create().greet(name)
}

