}

fun parseAmount(input: String): Long {
    // "12.34" -> 1234 (tiyin)
    val parts = input.split(".")
    val whole = parts[0].toLong()
    val fraction = parts[1].toLong()
    return whole * 100 + fraction
}

class Counter {
